const cfg = $("Configuração").first().json;
const workflows = $input.all().map((item) => item.json);
const norm = (value) => String(value ?? "").trim().toLowerCase();
const selected = workflows.filter((workflow) =>
  (workflow.tags ?? []).some((tag) => norm(tag.name ?? tag) === norm(cfg.requiredTag))
);

const sensitiveKey = /(authorization|api.?key|token|secret|password|cookie|private.?key|client.?secret|workflow.?id|spreadsheet.?id|document.?id|folder.?id|database.?id|prompt|messages|system.?message|json.?schema.?example)/i;
const placeholder = (key) => `{{${String(key || "SECRET").replace(/[^a-z0-9]+/gi, "_").toUpperCase()}}}`;

function sanitize(value, key = "") {
  if (sensitiveKey.test(key)) return placeholder(key);
  if (Array.isArray(value)) return value.map((entry) => sanitize(entry, key));
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([childKey, childValue]) => [childKey, sanitize(childValue, childKey)]));
  }
  if (typeof value !== "string") return value;
  return value
    .replace(/Bearer\s+[A-Za-z0-9._~+\/=\-]+/gi, "Bearer {{AUTH_TOKEN}}")
    .replace(/https?:\/\/(?:localhost|127\.0\.0\.1|10\.\d+\.\d+\.\d+|192\.168\.\d+\.\d+)(?::\d+)?/gi, "https://internal.example");
}

function publicNode(node) {
  const allowed = ["id", "name", "type", "typeVersion", "position", "disabled", "notes", "notesInFlow", "executeOnce", "retryOnFail", "maxTries", "waitBetweenTries", "onError"];
  const clean = Object.fromEntries(allowed.filter((key) => node[key] !== undefined).map((key) => [key, node[key]]));
  clean.parameters = sanitize(node.parameters ?? {});
  if (/(webhook|formTrigger)/i.test(node.type) && clean.parameters.path) clean.parameters.path = "WEBHOOK_PATH";
  if (/chainLlm/i.test(node.type) && clean.parameters.text) clean.parameters.text = "{{TEXT}}";
  if (node.credentials) {
    clean.credentials = Object.fromEntries(Object.keys(node.credentials).map((type) => [
      type,
      { id: `${type.toUpperCase()}_CREDENTIAL_ID`, name: `${type.toUpperCase()}_CREDENTIAL` },
    ]));
  }
  return clean;
}

function readMetadata(workflow) {
  const note = (workflow.nodes ?? []).find((node) =>
    node.type === "n8n-nodes-base.stickyNote" && String(node.parameters?.content ?? "").includes("@project-docs")
  );
  const meta = {};
  for (const line of String(note?.parameters?.content ?? "").split("\n")) {
    const match = line.match(/^([A-Za-z][A-Za-z0-9_-]*):\s*(.+)$/);
    if (match) meta[match[1]] = match[2].trim();
  }
  return meta;
}

function escapeMermaid(value) {
  return String(value).replace(/["\n\r]/g, " ").replace(/[<>]/g, "");
}

function makeMermaid(workflow) {
  const nodes = workflow.nodes ?? [];
  const ids = new Map(nodes.map((node, index) => [node.name, `N${index}`]));
  const lines = ["flowchart LR"];
  for (const node of nodes) lines.push(`  ${ids.get(node.name)}["${escapeMermaid(node.name)}"]`);
  for (const [source, outputs] of Object.entries(workflow.connections ?? {})) {
    for (const channel of outputs.main ?? []) {
      for (const target of channel ?? []) {
        if (ids.has(source) && ids.has(target.node)) lines.push(`  ${ids.get(source)} --> ${ids.get(target.node)}`);
      }
    }
  }
  return [...new Set(lines)].join("\n");
}

function stableHash(text) {
  let hash = 2166136261;
  for (let index = 0; index < text.length; index++) {
    hash ^= text.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, "0");
}

if (selected.length === 0) {
  return [{ json: { kind: "empty", requiredTag: cfg.requiredTag, discovered: workflows.length, message: "Nenhum workflow selecionado." } }];
}

return selected.map((workflow) => {
  const metadata = readMetadata(workflow);
  const nodes = workflow.nodes ?? [];
  const triggers = nodes.filter((node) => /(trigger|webhook)/i.test(node.type)).map((node) => node.name);
  const integrations = [...new Set(nodes.map((node) => node.type.split(".").pop()).filter(Boolean))].sort();
  const publicWorkflow = {
    name: metadata.project || workflow.name,
    nodes: nodes.map(publicNode),
    connections: workflow.connections ?? {},
    settings: { executionOrder: workflow.settings?.executionOrder ?? "v1" },
  };
  const workflowJson = JSON.stringify(publicWorkflow, null, 2);
  const mermaid = makeMermaid(workflow);
  const title = metadata.project || workflow.name;
  const summary = metadata.summary || "Resumo pendente de revisão humana.";
  const readme = [
    `# ${title}`,
    "", "## Visão geral", "", summary,
    "", "## Arquitetura", "", "```mermaid", mermaid, "```",
    "", "## Gatilhos", "", ...(triggers.length ? triggers.map((name) => `- ${name}`) : ["- Nenhum gatilho identificado"]),
    "", "## Integrações e tipos de nós", "", ...integrations.map((name) => `- ${name}`),
    "", "## Como importar", "", "1. Importe `workflow.sanitized.json` no n8n.", "2. Configure as credenciais indicadas por placeholders.", "3. Revise URLs, IDs e variáveis de ambiente.", "4. Teste manualmente antes de ativar.",
    "", "## Revisão", "", "Documento gerado deterministicamente. Contexto, resultados e decisões técnicas devem ser revisados por uma pessoa.",
  ].join("\n");
  const runbook = [`# Runbook — ${title}`, "", "## Inicialização", "- Validar credenciais e dependências.", "- Executar um teste manual.", "", "## Desativação", "- Desativar o workflow no n8n.", "- Registrar o motivo e a execução afetada.", "", "## Rollback", "- Restaurar uma versão revisada do JSON.", "- Revalidar em modo manual antes de reativar."].join("\n");
  const troubleshooting = [`# Troubleshooting — ${title}`, "", "## Checklist", "1. Consultar a execução com erro.", "2. Identificar o primeiro nó que falhou.", "3. Verificar credenciais, limites e disponibilidade das APIs.", "4. Validar o formato da entrada.", "5. Reexecutar apenas após revisar efeitos colaterais."].join("\n");
  const projectMetadata = {
    workflowId: workflow.id, title, summary, owner: metadata.owner || "PENDENTE",
    criticality: metadata.criticality || "PENDENTE", tags: (workflow.tags ?? []).map((tag) => tag.name ?? tag),
    triggers, integrations, nodeCount: nodes.length, connectionGroups: Object.keys(workflow.connections ?? {}).length,
    sourceUpdatedAt: workflow.updatedAt, reviewStatus: "draft", hash: stableHash(workflowJson),
  };
  return { json: {
    kind: "project", workflowId: workflow.id, title, dryRun: true, reviewRequired: true,
    metadata: projectMetadata,
    files: {
      "README.md": readme,
      "workflow.sanitized.json": workflowJson,
      "architecture.mmd": mermaid,
      "docs/runbook.md": runbook,
      "docs/troubleshooting.md": troubleshooting,
      "metadata.json": JSON.stringify(projectMetadata, null, 2),
      "AI_PROMPT.md": `Revise a documentação de ${title} sem inventar responsáveis, resultados, SLA ou regras de negócio. Liste dúvidas para revisão humana.`,
    },
  } };
});

const rows = $input.all().map((item) => item.json);
const projects = rows.filter((row) => row.kind === "project");
const empty = rows.find((row) => row.kind === "empty");
return [{ json: {
  status: "dry-run",
  selectedProjects: projects.length,
  payloads: projects,
  discoveredWorkflows: empty?.discovered ?? undefined,
  projects: projects.map((project) => ({
    workflowId: project.workflowId,
    title: project.title,
    hash: project.metadata.hash,
    files: Object.keys(project.files),
    reviewRequired: project.reviewRequired,
  })),
  message: empty?.message ?? "Arquivos preparados; nenhuma publicação foi realizada.",
} }];
